// yogananda_te.dart
// Paramhansa Yogananda quotes and articles (Telugu)

import '../articlesquotes.dart';

final yoganandaSaintTe = Saint(
  'yogananda',
  'Paramhansa Yogananda',
  'assets/images/paramhansa.jpg',
  [
    'మీరు మీ జీవితం సాధారణ మార్గంలో నడవనివ్వకండి; మరెవ్వరూ చేయని, ప్రపంచాన్ని ఆశ్చర్యపరిచే ఏదైనా చేయండి.',
    'విఫలత యొక్క కాలం విజయపు విత్తనాలను నాటడానికి ఉత్తమ సమయం.',
    'మీరు సాధ్యమైనంత సులభంగా ఉండండి; మీ జీవితం ఎంత సులభంగా మరియు సంతోషంగా మారవచ్చో చూడటానికి మీరు ఆశ్చర్యపోతారు.',
    'క్షణంలో శాంతిగా జీవించండి మరియు మీ ముందు ఉన్న అందాన్ని చూడండి. భవిష్యత్తు తనను తాను చూసుకుంటుంది.',
    'మన హృదయానికి మాత్రమే సంతోషం ఆత్మను సంతృప్తి పరచలేరు; మన సంతోషానికి అవసరమైనట్లుగా, ఇతరుల సంతోషాన్ని కూడా చేర్చడానికి ప్రయత్నించాలి.',
    'మీరు మీను మార్చుకోండి, అప్పుడు మీరు ప్రపంచాన్ని మార్చడంలో మీ భాగాన్ని పూర్తి చేసారు.',
    'సాధన నిరంతరంగా కొనసాగించడం ఫలితాలు తప్పనిసరిగా వస్తాయని నిర్ధారిస్తుంది.',
    'శాంతంగా, నిశ్శబ్దంగా ఉండండి, మీపై ఎప్పుడూ నియంత్రణలో ఉండండి. అప్పుడు మీరు ఎలా సులభంగా కలిసి ఉండాలో తెలుసుకుంటారు.',
    'నా ఆత్మ నా హృదయమార్గం ద్వారా నవ్వాలని, నా హృదయం నా కళ్ళ ద్వారా నవ్వాలని, దుర్దినమైన హృదయాలలో సంతోషాన్ని పంచగలుగుతాను.',
    'అసంతృప్తి కావాల్లి శక్తి మానవుని బానిసత్వానికి మూలం.',
    'సంతోషం మీ మనస్సు స్థితిపై ఆధారపడి ఉంటుంది, మీ ఆస్తుల స్థితిపై కాదు.',
    'విజయానికి మరియు ఆనందానికి రహస్యం మీలోనే ఉంది. మీరు బయట విజయాన్ని మరియు సంపదను కనుగొన్నా, కానీ మీలో కనుగొనలేకపోతే, మీరు నిజంగా విజయవంతులు కాదు.',
    'శాంతి ఆత్మ నుండి ఉద్భవిస్తుంది, మరియు నిజమైన ఆనందం వికసించే పవిత్ర అంతర్గత వాతావరణం.',
    'అంతా ధనాన్ని కలిగి ఉండడం, కానీ అంతర శాంతి లేకపోవడం అంటే సముద్రంలో స్నానం చేస్తూ త్రాగడానికి నీరు లేక మరణించడం లాంటిది.',
    'ఒక నిజమైన విజయవంతమైన వ్యక్తి సంతోషంగా మరియు సంతృప్తిగా ఉంటాడు మరియు తన స్వంత సూత్రాల ప్రకారం జీవిస్తాడు.',
    'మీరు నిజమైన శాంతి మరియు సంతోషాన్ని మీలోనే కనుగొనాలి. మీ బాహ్య అనుభవాలు కేవలం ఆనందం మాత్రమే కావాలి.',
    'ఆనందంగా ఉండడం కష్టం కాదు. శాంతిగా సంతోషంగా ఉండడం కష్టమైన భాగం. అది ఆદર્શం.',
    'ప్రతి ప్రస్తుత క్షణాన్ని పూర్తిగా జీవించండి, భవిష్యత్తు తానే చూసుకుంటుంది.',
    'శాంతి యొక్క ఉనికిని మీరు ఎంత ఎక్కువగా అభ్యాసం చేస్తే, ఆ శక్తి మీ జీవితంలో ఎంత ఎక్కువగా ఉనికిని అనుభవిస్తారు.',
    'అస్తిత్వం యొక్క మొత్తం రహస్యం భయాన్ని లేకుండా ఉండడమే.',
    'కరుణ అనేది ఆత్మలు, కుటుంబాలు మరియు దేశాల మధ్య ఉన్న అన్ని గోడలను కరిగించే వెలుగు.',
    'జీవితంలో కొంచెం ఆనందం చాలా వస్తువుల కంటే మెరుగైనది.',
    'మీరు ఆడించబడే పాత్రను ఎలా నిర్వహిస్తున్నారో అది మీ నిజమైన అస్తిత్వాన్ని ప్రభావితం చేయదు అని గ్రహించండి.',
    'ఒక మనిషి శ్రమకు ఉన్న అత్యున్నత బహుమతి అతను దానికి పొందే ద్రవ్యములో కాదు, కానీ అది ద్వారా అతను ఎలా మారుతాడో ఆ మార్పులో ఉంది.',
    'మీరు ఆధ్యాత్మిక చైతన్యంలోని ఆశీర్వాదాలకు అర్హులు.',
    'ధ్యాన సాధన ద్వారా, మీరు మీ హృదయంలో ఒక పోర్టబుల్ పరదీస్తున్నారని కనుగొంటారు.',
    'ఆత్మ ధ్యానం చేయడం ఇష్టపడుతుంది, ఎందుకంటే ఆత్మతో సంబంధంలోనే దాని అత్యంత ఆనందం ఉంది.',
    'ధ్యానం మీ ఆత్మను శరీర బంధనాల నుండి పునరుత్తేజం చేసేందుకు అత్యుత్తమ మార్గం.',
    'ధ్యానం అనేది దేవుని శాంతి మీ ఆత్మలో ప్రవహించే వసంతం.',
    'తక్కువ సమయం లో లోతుగా ధ్యానం చేయడం, మనసు అల్లకల్లోలంగా ఉండి ఎక్కువ గంటలు ధ్యానం చేయడాన్ని కంటే మంచిది.',
    'నిశ్శబ్దంగా ఉండి, నేను దేవుడు అని తెలుసుకో.',
    'అత్యుత్తమ ప్రయత్నం చేసే భక్తుడే దేవునిని కనుగొంటాడు. నిత్యం కారణాలు వెతుకుతున్నవాడు కాదు.',
    'మీరు ధ్యానం చేస్తే, మీరు Him కి అన్ని చోట్ల తలుపులు తెరుచుకుంటున్నాయి కనుగొంటారు.',
    'దైవాన్ని కనుగొనడానికి మీ ప్రయత్నాల్లో ఉల్లాసంగా లేదా అసహనంగా ఉండకండి. సహనంగా ఉండండి. మీ దివ్య లక్ష్యానికి శాంతిగా, నిశ్చలంగా కదలండి.',
    'మనస్సు ఒక చానెల్‌గా పనిచేస్తుంది, దాని ద్వారా విశ్వజ్ఞానం మన చైతన్యంలో ప్రవహిస్తుంది.',
    'మీరు దేవునిని ఎంత ఎక్కువగా ప్రేమిస్తే, మీరు ఇతరులను కూడా అంత ఎక్కువగా ప్రేమించగలుగుతారు, ఎందుకంటే మీరు వారిలో దేవునిని చూడగలుగుతారు.',
    'ఒక వ్యక్తి యొక్క స్వభావాన్ని పరీక్షించడానికి ఉత్తమమైన పరీక్ష ఏమిటంటే, వారు తమకు ఏమీ చేయలేని వారిని ఎలా వ్యవహరిస్తారు.',
    'మీరు కోరుకున్నది చేయకండి, అప్పుడు మీరు ఇష్టమైనది చేయవచ్చు.',
    'విజయానికి మరియు ఆనందానికి రహస్యం మీలోనే ఉంది.',
    'మీరు అన్ని బంధనాల నుండి విముక్తి పొందకముందు నిజంగా సంతోషంగా ఉండలేరు.',
    'ప్రేమ ఎలాంటి ప్రతిఫలం ఆశించకుండా ఇవ్వడం.',
    'ప్రియమైనవాడికి సంపూర్ణతను కోరడం, ఆ ఆత్మను ఆలోచించేటప్పుడు శుద్ధ ఆనందాన్ని అనుభవించడం, దేవతల ప్రేమ; మరియు అది నిజమైన స్నేహానికి సంబంధించిన ప్రేమ.',
    'ప్రేమ అనేది ఆత్మలు, కుటుంబాలు మరియు దేశాల మధ్య ఉన్న అన్ని గోడలను కరిగించే వెలుగు.',
    'మీరు అనుభవించగల గొప్ప ప్రేమ అనేది ధ్యానంలో దేవునితో సమ్మేళనంలో ఉంటుంది.',
    'కలిసిన ప్రేమ కోసం దుఃఖించవద్దు... ప్రేమ ఎప్పుడూ కోల్పోబడదు, కానీ అది అనేక హృదయాల్లో మీతో దొరకదీస్తుంది.',
    'మీ ప్రేమను ఒకసారి ఇచ్చినప్పుడు, అది శాశ్వతంగా ఉండాలి. మీరు ఆ వ్యక్తికి దగ్గరగా ఉండాలనే కోరుకుంటున్నందుకు కాదు, కానీ ఆ ఆత్మకు పరిపూర్ణతను కోరుకుంటున్నందుకు.',
    'ప్రపంచం మొత్తం ఆత్మకు ఒక క్రీడా స్థలం.',
    'మీరు ఆయనతో సమ్మేళనం ఉన్నప్పుడు, ఈ ప్రపంచంలోని అన్ని విధ్వంసాలు ఆ ఆనందం మరియు శాంతిని తీసుకుపోలవు.',
    'దైవం యొక్క అనంత ప్రేమలో, నా శాశ్వత హృదయం నాలోని ప్రతీ విషయాన్ని ఉంచడానికి పెద్దది.',
    'నా హృదయం శాశ్వత ప్రేమ యొక్క దేవాలయం.',
    'నిజమైన మిత్రుడిగా ఉండాలంటే, ఇతరులను మీరే ప్రేమించాలి, ఎందుకంటే అప్పుడు మాత్రమే మీరు వారి అవసరాలు మరియు దుఃఖాలను అర్థం చేసుకోగలరు.',
    'ప్రేమ అనేది ఒక భావన కాదు; ఇది సృష్టి యొక్క కేంద్రంలో ఉన్న సత్యం.',
    'దైవం యొక్క ప్రేమ, ఆత్మ యొక్క ప్రేమ, ఇది సమస్తాన్ని ఆహరించుకునే ప్రేమ.',
    'రాత్రి-దినం దేవుని ప్రేమతో మత్తులో ఉండి, దేవుని తప్ప మరేదీ తెలియనంతగా ఉండండి.',
    'ఆత్మ మరియు ఆత్మస్వరూపం మధ్య ఉన్న ప్రేమ అనేది పరిపూర్ణమైన ప్రేమ, మీరు అందరూ వెతుకుతున్న ప్రేమ.',
    'మానవుడిగా మీరు పరిమితులు ఉన్నారు, కానీ దేవుని కుమారుడిగా మీరు అపరిమితులు.',
    'మనిషి మనస్సు దేవుని శక్తివంతమైన చైతన్యానికి ఒక చిమ్మకారు.',
    'మీ ఆలోచనలు మీను రూపొందిస్తాయి. మీరు చెడ్డవాడైతే, అది మీ చెడు ఆలోచనల ఫలితమే. మీరు మంచి వ్యక్తి అయితే, అది మీ మంచి ఆలోచనల వల్లే.',
    'మీ ఆలోచనలు చెడు మీద కేంద్రీకరించడానికి అనుమతిస్తే, మీరు స్వయంగా కీడు అవుతారు.',
    'మీ లోని దేవుడి శక్తి, అపరిమిత నియంత్రణ శక్తి, సూపర్ కాన్షియస్ మైండ్ లో ఉంది.',
    'మీరు మరణం తరువాత మీరు ముందుగా ఉన్నట్లే ఉంటారు. ఎలాంటి మార్పు ఉండదు; మీరు కేవలం శరీరాన్ని విడిచిపెడతారు.',
    'మనసు ఒక శక్తి, ఇది ప్రపంచాన్ని గెలవడానికి ఉపయోగించవచ్చు.',
    'మీ అసంపూర్ణతల నుండి మిమ్మల్ని విముక్తి పొందించడానికి మృతి మీద ఆధారపడకండి.',
    'మీలో మీరు కావాలనుకునే ప్రతి విషయాన్ని సాధించగల శక్తి ఉంది; ఆ శక్తి మీ ఇచ్ఛలో ఉంది.',
    'మనసు పిచ్చి కోతికి సమానం, మరియు ఇచ్ఛ శక్తి దానిని కట్టడానికి ఉన్న రశీది.',
    'నిజమైన ఆత్మ విశ్లేషణ అనేది పురోగతికి అత్యంత కళ.',
    'మొత్తం విఫలత కాలం విజయం యొక్క విత్తనాలను నాటడానికి అత్యుత్తమ సమయం.',
    'మన ఆలోచనలు మనను రూపొందిస్తాయి. మనం ఏమి ఆలోచిస్తామో, అదే మనం అవుతాము.',
    'మీరు ఎంత ఎక్కువగా కేంద్రీకరిస్తే, మీరు చేయాలనుకునే వాటిని చేయడం అంత ఎక్కువగా సాధ్యం అవుతుంది.',
    'మనసును అధిగమించడం అంటే స్వేచ్ఛగా ఉండడం.',
    'మరణం నిజంగా అందంగా ఉంటుంది; ఇది చెడు విషయం అయితే, దేవుడు మనకు ఇది జరగనివ్వడు.',
    'ఈ వ్యాధి మరియు ఆరోగ్యం, దుఃఖం మరియు ఆనందం యొక్క మాయను విసర్జించండి. దానిని మించి ఎగురండి. ఆత్మగా మారండి.',
    'అన్ని ఆత్మలు దేవుని నుండి వస్తాయి—శుద్ధ ఆత్మ యొక్క వ్యక్తీకృత కిరణాలు—మరియు తమ స్వదేశమైన పరిపూర్ణతకు తిరిగి అభివృద్ధి చెందుతాయి.',
    'తరంగం సముద్రంతో సమానం, కానీ అది మొత్తం సముద్రం కాదు. కాబట్టి సృష్టి యొక్క ప్రతి తరంగం ఆధ్యాత్మిక శాశ్వత సముద్రం యొక్క భాగం.',
    'ఈ జీవితం చిన్నది, ప్రపంచంలోని అహంకారాలు తాత్కాలికమైనవి, కానీ ఇతరుల కోసం జీవించేవారే నిజంగా జీవిస్తారు, మిగతా వారు జీవించడంలో కంటే మరణించడంలో ఎక్కువగా ఉన్నారు.',
    'మీరు ఎప్పుడైనా పోరాడే అత్యంత మహత్తరమైన యుద్ధం మీ స్వంత మనసుతోనే ఉంటుంది.',
    'ప్రతి రేపు ప్రతి నేడు ద్వారా నిర్ణయించబడుతుంది.',
    'ఏమీ భయపడకండి. ఎవరినీ ద్వేషించకండి, అందరికి ప్రేమ ఇవ్వండి, దేవుని ప్రేమను అనుభవించండి, ప్రతి ఒక్కరిలో ఆయన ఉనికిని చూడండి.',
    'మీ ఆలోచనలు లేదా అద్భుతమైన ఆలోచనలు కాకుండా, మీ సాధారణ రోజువారీ అలవాట్లు మీ జీవితాన్ని నియంత్రిస్తాయి.',
    'ప్రపంచం మొత్తం, అతను ఎక్కడకు వెళ్ళాలని తెలుసుకుని, అక్కడికి చేరుకోవాలనే సంకల్పం ఉన్న వ్యక్తి కోసం పక్కన నిలబడుతుంది.',
    'ఒక వ్యక్తి యొక్క స్వభావాన్ని పరీక్షించడానికి ఉత్తమమైన పరీక్ష అంటే, వారు తమకు ఏమీ చేయలేని వారిని ఎలా ప్రవర్తిస్తారు.',
    'మీరు ఏమి ఆలోచిస్తే, మీరు అవుతారు. మీరు ఏమి అనుభవిస్తే, మీరు ఆకర్షిస్తారు. మీరు ఏమి కల్పిస్తే, మీరు సృష్టిస్తారు.',
    'జీవితంలో క్రీడాకారుడిగా ఉండండి; కానీ నిజమైన పోటీ అంతర్గతంగా నడిచే పోటీని గుర్తుంచుకోండి.',
    'ప్రతి సాధకుడు తన అశాంతిని తొలగించడానికి ఉద్దేశపూర్వకంగా లోతైన ధ్యాన చర్యలను చేపట్టాలి.',
    'సంపూర్ణ ఆరోగ్యం, సంపూర్ణ ఆనందం, మరియు సంపూర్ణ విజయం యొక్క రహస్యం మీ స్వంత మనసును నియంత్రించడంలో ఉంది.',
    'మీరు పునర్జన్మల కాలంలో మనం సృష్టించిన చైతన్యానికి మొత్తం సమాహారం.',
    'కర్మ యొక్క చట్టం శిక్ష కాదు; ఇది కారణం మరియు ఫలితానికి సంబంధించిన చట్టం. ఇది సంపూర్ణ న్యాయానికి సంబంధించిన చట్టం.',
    'ప్రతి మనిషికి తన స్వంత మార్గాన్ని ఎంచుకునే హక్కు ఉంది, కానీ అతను తన ఎంపికల ఫలితాలను కూడా అంగీకరించాలి.',
    'మీ అదృష్టం మీ చేతుల్లో ఉంది, ఎందుకంటే మీ ఆలోచనలు మరియు చర్యలను మార్చే శక్తి మీలో ఉంది.',
    'మీ ఇష్టశక్తి మీలోని దేవుని చిత్రానికి సాధన.',
    'ఒక శక్తివంతమైన ఇచ్ఛ, తన గతి శక్తితో, తన సాకారం కోసం ఒక మార్గాన్ని సృష్టిస్తుంది.',
    'మీ ఇష్టశక్తిని నిర్మాణాత్మకంగా ఉపయోగించుకోవాలని నిర్ధారించుకోండి, హానికరమైన ఉద్దేశ్యాలు లేదా తక్కువ విషయాల కోసం కాదు.',
    'మీ జీవితం యాదృచ్ఛిక ఫలితం కాదు, మీ స్వంత సృష్టి ఫలితం.',
    'జీవితానికి ఉద్దేశ్యం ఇతరుల కోసం జీవించడం మరియు దేవునిలో జీవించడం.',
    'అతిపెద్ద పాపం అంటే మీరే మీర్ని బలహీనుడిగా భావించడం.',
    'ప్రపంచం ఆయన ఉనికికి విస్తృతమైన ఆలయం.',
    'ఈ జీవితానికి కింద ఉన్న నీడల వెనుక ఆయన అద్భుతమైన కాంతి ఉంది.',
    'ఆత్మ శరీరంలో లేదు, కానీ శరీరం ఆత్మలో ఉంది.',
    'అన్నీ దేవుడు. అన్నీ ఆత్మ. అన్నీ ఒకటే.',
    'భౌతిక ప్రపంచం ఒక కల, కానీ మీ మనసు శక్తి ద్వారా మార్చగల కల.',
    'ప్రపంచం మనకు శక్తివంతులుగా మారేందుకు వచ్చే గొప్ప వ్యాయామశాల.',
    'ప్రత్యేకమైన ఆత్మ యొక్క మాయే అన్ని బాధల మూలం.',
    'మీరు శాశ్వత ఆత్మ సముద్రం యొక్క భాగం.',
    'మీరు ఎంత ఎక్కువగా ధ్యానం చేస్తే, మీరు మీ శరీరం కాదు, కానీ అమరాత్మ అని తెలుసుకుంటారు.',
    'జీవితానికి నిజమైన అర్థం, మీరు దేవునితో ఒకటిగా ఉన్నారని గ్రహించడం.',
    'మీరు ఇతరులకు మంచిని చేయడానికి ఎంత ఎక్కువగా బయటకు వస్తే, మీ హృదయాలు అంత ఎక్కువగా శుద్ధి అవుతాయి.',
    'ప్రపంచానికి మీ వద్ద ఉన్న ఉత్తమాన్ని ఇవ్వండి, అప్పుడు ఉత్తమం మీకు తిరిగి వస్తుంది.',
    'సంపత్తి యొక్క చట్టం స్వార్థం యొక్క చట్టం ద్వారా నియంత్రించబడదు, కానీ నిరస్వార్థత యొక్క చట్టం ద్వారా నియంత్రించబడుతుంది.',
    'నిజమైన విజయానికి, నిజమైన ఆనందానికి ఉన్న గొప్ప రహస్యం ఇది: ప్రతిఫలం కోరని వ్యక్తి, పూర్తిగా స్వార్థరహితమైన వ్యక్తి, అత్యంత విజయవంతుడవుతాడు.',
    'ఇతరులను సేవించడం అంటే దేవునిని సేవించడం.',
    'క్రియ యోగా అనేది మానవ అభివృద్ధిని వేగవంతం చేయడానికి ఉపయోగించే ఒక సాధనం, జీవ శక్తి ద్వారా మనస్సును నియంత్రించడం ద్వారా, మరియు ఇది అనంతానికి చేరుకునే అత్యంత శాస్త్రీయ మార్గం.',
    'క్రియ యొక్క అనంత ఫలితాలు అత్యంత శాంతి మరియు ఆనందాన్ని తీసుకువస్తాయి, అన్ని సుఖమైన శారీరక అనుభవాల ఆనందాలను మించిపోయి.',
    'ధ్యానంలో అనుభవించిన ఆనందం ద్వారా, నేను వేల నిద్రల విశ్రాంతిని పొందుతాను, ఇది ప్రగతిశీల యోగికి సాధారణ నిద్రను అవసరమయ్యేలా చేయదు.',
    'ఆత్మ-సాక్షాత్కారం యోగం లేదా "సత్యంతో ఏకత్వం" — ఆత్మ యొక్క సమగ్ర జ్ఞానంతో సత్యాన్ని నేరుగా గ్రహించడం.',
    'ఈ ఆధ్యాత్మిక చర్యల మార్గంలో, సాధనలో ఉన్న అసంపూర్ణ ప్రయత్నానికి నష్టమేమీ ఉండదు, లేదా వ్యతిరేక ఫలితాల సృష్టి ఉండదు.',
    'చిన్నదైన నిజమైన ధర్మం కూడా పునరుత్తాన మరియు మరణం యొక్క పునరావృత చక్రాలలో ఉన్న మహా భయాన్ని నుండి రక్షిస్తుంది.',
    'యోగం ఆధ్యాత్మిక చర్యల మార్గం, భావనను సాకారం చేయడంలో అపరాధరహితమైనది; ఈ మార్గాన్ని స్వీకరించిన వారు ప్రతి ప్రయత్నం శాశ్వతమైన ప్రయోజనాన్ని పొందుతారు.',
    'భౌతిక ప్రపంచంలో అన్ని విజయాలు స్పష్టమైన ఫలితాల ద్వారా గుర్తించబడతాయి; ఆధ్యాత్మిక మార్గంలో, ఫలితాలు మానసికమైనవి, స్పష్టంగా కనిపించవు, కానీ శాశ్వతంగా ప్రయోజనకరమైనవి.',
    'ఆధ్యాత్మిక ఫలితాలు చైతన్యంలోని సున్నితమైన మార్పులుగా ప్రారంభమవుతాయి, అంతర్గత అస్తిత్వం యొక్క పురోగతిని సూచిస్తూ.',
    'నిజమైన ధర్మం మార్పు చెందని సూత్రాలను కలిగి ఉంటుంది, ఇవి మనిషిని వ్యాధి, దుఃఖం మరియు అజ్ఞానం నుండి శాశ్వతంగా రక్షిస్తాయి.',
    'చరిత్రను మర్చిపోండి, ఎందుకంటే గతంలో ఉన్న జీవితం అనేక అవమానాలతో నిండిన చీకటిలో ఉంది; మానవ ప్రవర్తన దివ్యమైనది మీద నిలబడే వరకు నమ్మకమైనది కాదు.',
    'భవిష్యత్తులో ప్రతి విషయం మెరుగుపడుతుంది, ఒకరు ప్రస్తుతంలో నిజాయితీగా ఆధ్యాత్మిక ప్రయత్నం చేస్తే.',
    'మీరు మరియు ఎప్పుడూ ఆత్మ యొక్క పరిపూర్ణ ప్రతిబింబంగా ఉంటారు; ప్రస్తుతం మీరు మృత్యువుతో ఉన్నారని ఊహించినా, మీ నిజమైన స్వరూపంపై ధ్యానం మీ ఆత్మ స్వభావాన్ని గుర్తు చేస్తుంది.',
    'మీరు అమరుడైనందున, భూమి పరిమితులతో మీను భారంగా తీసుకోకండి.',
    'ధ్యానం అంటే ఆత్మతో ఒకటవడం, శరీర మరియు పరిమితుల చింతనను తొలగించడం, మరియు వ్యక్తి ఒక ఆత్మ అని గుర్తించడం.',
    'ధ్యానం దేవుని ఉనికిని నిరూపిస్తుంది.',
    'ఆకాశం, పర్వతాలు లేదా సముద్రాన్ని చూస్తున్న మనిషి దివ్య ఉనికిని గుర్తించడు; సృష్టికర్త యొక్క సున్నితమైన కాంతి శిక్షణ పొందని చూపుకు కనిపించదు.',
    'దేవుడు, అనంతమైనవాడు, ఏ రూపానికి పరిమితమవ్వలేడు, అయినప్పటికీ అన్ని రూపాలలో ప్రकटమవుతాడు; ఆయన ప్రతి మనిషిలో మరియు ప్రతి సంత్‌లో సమానంగా ఉన్నాడు.',
    'జీవుల మధ్య నిజమైన తేడా లేదు; అందరూ తల్లి ప్రకృతికి చెందిన ఉత్పత్తులు, ఒకే ఆధారమైన దివ్యత్వం ద్వారా పోషించబడ్డారు.',
    'వారి కనిపించే వైవిధ్యం ఒక మేధస్సు యొక్క ఏకత్వంలో నాటుకుపోయింది, ఈ సత్యాన్ని గ్రహించడం ముక్తి మరియు దేవునితో ఏకత్వం.',
    'ఒక విముక్తుడైన వ్యక్తి అన్ని ప్రాణుల్లో మరియు అన్ని సృష్టిలో కేవలం ప్రభువును మాత్రమే చూస్తాడు.',
    'దేవుడు చైతన్యం; విశ్వంలో మానసికత లేదా చైతన్యాన్ని తప్ప మరేం లేదు.',
    'సంస్కృత పదం దేవుడు — సత్-చిత్-ఆనంద — శాశ్వతమైన సత్యం (సత్), అనంతమైన చైతన్యం (చిత్), మరియు ఎప్పటికీ కొత్త ఆనందం (ఆనంద) ను సూచిస్తుంది.',
    'దేవుడు అన్ని మనుషుల ఆత్మగా ఉన్నప్పటికీ, సృష్టితో ఆయన కలిసిపోదు; అయితే, దేవునితో నిండిన మనుషులు, విశ్వ మాయకు గురవుతారు.',
    'నిజమైన జ్ఞానం ఒకే చైతన్యం ఎలా అన్ని విషయాలుగా మారుతుందో అర్థం చేసుకోవడమే.',
    'జ్ఞానులు తప్పించుకోలేని మార్పుల కోసం బాధపడరు; భౌతిక విషయాలు దేవుని చైతన్యంలో తక్కువ విలువైనవి, ఎందుకంటే అవి శాశ్వతం కాదు.',
    'వారు మృత్యువుల ఆందోళనను అధిగమించి, శరీరంతో ఐక్యత నుండి విముక్తి పొందిన శాంతిని అనుభవిస్తారు.',
    'అలాంటి భక్తులు అచలమైన పరిపూర్ణతను చేరినప్పుడు, వారు జీవితంలోని మార్పులను చూసి, వాటి వల్ల కదిలించబడరు.',
    'మార్పుల అలలతో ఐక్యత కలిగి ఉండటం దుఃఖానికి దారితీస్తుంది; మార్పు కోసం జీవించడం శాశ్వతం నుండి వేరుపడటం.',
    'జ్ఞానులు స్నేహితులు, కుటుంబం లేదా ఆస్తుల నుండి శాశ్వత ఆనందాన్ని ఆశించరు; అమరాత్మపై ధ్యానం చేయడం శాశ్వత శాంతిని అందిస్తుంది.',
    'ఆధునిక జీవితం అసంతృప్తికరంగా ఉంది; ఇది చాలా ఇష్టాలు, ఆందోళనలు మరియు తాత్కాలిక ఆనందాలను ఇస్తుంది, ఇవి చివరికి దుఃఖానికి దారితీస్తాయి.',
    'ఈ ప్రపంచంలో ఎలాంటి భద్రత లేదు; ఎప్పుడైనా అవగాహన వ్యాధి లేదా దురదృష్టం కారణంగా శరీరాన్ని విడిచిపెట్టడానికి బలవంతం చేయబడవచ్చు.',
    'కాలం మరియు స్థలంలో మార్పుల శాశ్వతమైన ప్రపంచంలో రూపం మరియు వ్యక్తీకరణలో నిరంతర మార్పు జరుగుతుంది, కానీ ఈ మార్పుల లోని ఆత్మ శాశ్వతంగా ఉంటుంది.',
    'మానవుని ఆత్మ మరియు విశ్వం యొక్క ఆత్మ శాశ్వతమైనవి — కృష్ణ లేదా క్రైస్తవ చైతన్యం — ఆత్మ యొక్క వ్యక్తీకరణలు.',
    'మొదట, తప్పు ఆలోచనలు మరియు అలవాట్ల నుండి స్వతంత్రంగా ఉండండి; రెండవది, మంచి అలవాట్లను స్థాపించండి మరియు మంచి కర్మలు చేయండి.',
    'మీరు ప్రయత్నిస్తూనే ఉంటే, మీరు మెరుగుపడతారు; ఒక సంత్ అనేది కేవలం ఎప్పుడూ ఆపని పాపి.',
    'ఎప్పుడూ ఓడిపోకండి; మీరు ఆలోచించే ప్రతి ఆధ్యాత్మిక ఆలోచన మీ శాశ్వత మిత్రుడిగా ఉంటుంది.',
    'మీరు పొందే ప్రతి దుష్ట భావన మీ శత్రువుగా మారుతుంది, మీరు దాన్ని చంపే వరకు.',
    'మీ జీవితంలో భౌతిక మరియు ఆధ్యాత్మిక కర్తవ్యాలను సమతుల్యం చేయండి; ఆ సమతుల్యం అత్యున్నత సంతోషాన్ని తీసుకువస్తుంది.',
    'జాగ్రత్తగా ఉండండి, ఇక నిద్రపోకండి; మానవ చైతన్యాన్ని విముక్తి పొందించడం అంటే అధ్యయనము, ధృవీకరణ, కేంద్రీకరణ మరియు ధ్యానము ద్వారా దాన్ని శిక్షణ ఇవ్వడం.',
    'శరీరంలోని నిరంతర మార్పులపై దృష్టిని మళ్లించి, జీవశక్తి యొక్క సూక్ష్మ, స్థిరమైన కంపనాలు మరియు ఉన్నత మానసిక స్థితుల వైపు మళ్లించండి.',
    'దేవుని శాశ్వత ఆనందాన్ని ఎంచుకోండి, ఇది కొంతకాలం కొన్ని ఆనందాలను వదులుకోవడం ద్వారా సాధించవచ్చు, అనిత్యమైన భౌతిక సంతోషం కంటే.',
    'మీరు శరీరంగా కాకుండా, దాని వెనుక ఉన్న ఆనందభరిత చైతన్యంగా మరియు అమరమైన జీవితంగా ఆలోచించండి.',
    'సత్యాలు మీలోని ఆత్మలో అవగాహన పొందకుండా, మీకు సత్యాలు కావు; అవగాహన లేకుండా, అవి కేవలం ఆలోచనలుగా మిగిలి ఉంటాయి.',
    'ఆధ్యాత్మిక చైతన్యం అస్పష్టమైన ధార్మిక ఆలోచనలలో కాదు, కానీ ఆత్మ-జ్ఞానం సాధనలో ఉంది.',
    'సముద్రాన్ని ఒక కప్పులో పొందడం కష్టమే, కప్పు సామర్థ్యం పెరిగితేనే అది సాధ్యం — అలాగే, దేవుని అర్థం చేసుకోవడానికి మన మానసిక సామర్థ్యాలు పెరగాలి.',
    'స్వయ అభివృద్ధి ద్వారా పొందిన సామర్థ్యాన్ని స్వీకరించడం సూచిస్తుంది; ఇది కేవలం విశ్వాసం కంటే వేరుగా ఉంది.',
    'మానవ చైతన్యంలోని బలహీనతను వదలండి మరియు రాజమార్గంలో ఎదుగండి.',
    'ఇంకా అన్నీ వేచి ఉండవచ్చు; మీరు దేవుని కోసం చేసే శోధన వేచి ఉండదు.',
    'ఈ ఉపదేశాలు కేవలం ఉపన్యాసాలు కాదు, కానీ మీను విముక్తి కలిగించే సత్యాలు.',
    'క్రియా యోగా జీవశక్తిని ఉపయోగించి అశాంతమైన మనసును శాంతింపజేస్తుంది మరియు అనంతంతో నేరుగా సంబంధం ఏర్పరుస్తుంది.',
    'ధ్యానం యొక్క ఆనందం సాధారణ శారీరక సంతోషాలను మించుకుని, నిద్ర కంటే లోతుగా ఉంటుంది.',
    'ఆనందం అనేది బాహ్య సంఘటనలకు ప్రతిస్పందన కాదు, కానీ ఆధ్యాత్మిక సాధన ద్వారా చేరుకునే చైతన్య స్థితి.',
    'నిజమైన ధర్మం అనేది దైవిక సత్యాన్ని చైతన్యంగా అనుభవించడం, కేవలం మేధస్సు ఒప్పుకోవడం కాదు.',
    'ఆధ్యాత్మిక ప్రయత్నం అంతర్గత శాంతికి మాత్రమే కాదు, భయము మరియు బాధ నుండి ఆత్మను రక్షిస్తుంది.',
    'ఆధ్యాత్మిక సాధన యొక్క నిజమైన ప్రయోజనాలు సూక్ష్మమైనప్పటికీ శాశ్వతమైనవి; అవి చైతన్యాన్ని శాశ్వతంగా మార్చుతాయి.',
    'దివ్యమైనది లో నాటుకట్టడం, ప్రపంచం అందించే తాత్కాలిక ఆనందాల కంటే ఎక్కువగా భద్రతను అందిస్తుంది.',
    'ధ్యానం అంతరజ్ఞానాన్ని తెరుస్తుంది, జీవితం మరియు ఆత్మ గురించి దాచిన సత్యాలను ప్రదర్శిస్తుంది.',
    'దివ్య ఉనికి సున్నితమైనది, సాధారణ ఇంద్రియాలు గుర్తించలేని దాటి ఉంటుంది.',
    'అన్ని రూపాలు, విభిన్నమైనప్పటికీ, ఒకే ఆధారమైన దివ్యత్వం ద్వారా పోషించబడుతున్నాయి.',
    'ముక్తి అనేది దేవునితో ఉన్న ఏకత్వాన్ని గుర్తించడం ద్వారా వస్తుంది, ఇది అన్ని బాహ్య వ్యత్యాసాలను మించిస్తుంది.',
    'ప్రపంచ సంబంధాలు మరియు ఆస్తులు చివరికి మాయమవుతాయి; శాశ్వతమైనది ఆధ్యాత్మిక అవగాహన.',
    'అమరత్వం ఆత్మ యొక్క నిజమైన స్వభావం; తాత్కాలిక రూపాలు గుర్తింపును నిర్వచించకూడదు.',
    'సృష్టి యొక్క సారాంశం చైతన్యం, అపారంగా ప్రकटమవుతూ కూడా మౌలికంగా ఒకటే.',
    'నిజమైన జ్ఞానం కేవలం మేధస్సు జ్ఞానాన్ని మించిపోయి, అంతర్గత అవగాహనలో స్థిరపడుతుంది.',
    'మనిషి అశాంతి శాశ్వతంలో చైతన్యం కేంద్రీకరించగానే కరిగిపోతుంది.',
    'ఆత్మలో స్థిరంగా ఉన్నవారిపై మార్పు చక్రం తన శక్తిని కోల్పోతుంది.',
    'ఆధ్యాత్మిక శాంతి కోసం ఉన్న ఆకాంక్ష, ఏ విధమైన భౌతిక కోరిక కంటే లోతైన ప్రేరణ.',
    'ఒకరి ఆధ్యాత్మిక స్థితి, ఆ వ్యక్తి శాంతిని అనుభవించగల సామర్థ్యాన్ని నిర్ణయిస్తుంది.',
    'ఒక సంత్ యొక్క పట్టుదల అనేది అతని అజ్ఞానంపై విజయం కొరకు కొలమానం.',
    'ప్రతి ఆధ్యాత్మిక ఆలోచన శాశ్వత శాంతికి ఒక ఆధారం ఏర్పరుస్తుంది.',
    'దివ్య సత్యంపై నిరంతరం ఆలోచించడం, individual\'s ఆధ్యాత్మిక పురోగతిని బలపరుస్తుంది.',
    'తప్పు ఆలోచనలు మించిపోయేవరకు శత్రువులుగా మారతాయి.',
    'అత్యుత్తమ సంతోషం భౌతిక బాధ్యతలు మరియు ఆధ్యాత్మిక భక్తి మధ్య సమన్వయం నుండి ఉద్భవిస్తుంది.',
    'శరీర గుర్తింపును మించిపోయేలా చైతన్యాన్ని శిక్షణ ఇవ్వడం అంతర స్వాతంత్ర్యాన్ని ఆవిష్కరిస్తుంది.',
    'సతత ధ్యానంతో స్థిరమైన ఉన్నత చైతన్య స్థితులు ఉద్భవిస్తాయి.',
    'దివ్య ఆనందాన్ని ఎంచుకోవడం ఒకరి కర్మను మోక్షం వైపు ఆకారీకరించును.',
    'మానవ గుర్తింపు ఒక మాయ, ఇది లోతైన ఆధ్యాత్మిక అవగాహనలో కరిగిపోతుంది.',
    'సత్యాలు అనుభవం ద్వారా అంతర్గతంగా గ్రహించినప్పుడు మాత్రమే జీవితం మారుతుంది.',
    'దేవుని అవగాహన అనేది అన్ని మేధస్సు నమ్మకాలకు మించి ఉన్న అత్యంత లక్ష్యం.',
    'దివ్య సత్యానికి one\'s సామర్థ్యాన్ని పెంచడం ఆధ్యాత్మిక అభివృద్ధికి కీలకం.',
    'మాత్రం విశ్వాసం చైతన్యాన్ని విముక్తి చేయదు; ఆచరణ ద్వారా అవగాహన మాత్రమే విముక్తి ఇస్తుంది.',
    'ఆధ్యాత్మిక మార్గం రాజమార్గం, మృతికి మించి ఎగసేందుకు ధైర్యాన్ని కోరుతుంది.',
    'దేవుని కోసం అన్వేషణ అన్ని తక్కువ లక్ష్యాలపై ప్రాధాన్యత పొందాలి.',
    'ఈ ఉపదేశాలు జీవనదాయకమైన సత్యాలు, అవి అభ్యాసిక భావనలు కాదు.',
    'ధ్యానం సాధారణ క్షణాలను అమరత్వానికి దారితీసే అడుగులుగా మార్చుతుంది.',
    'ఆనందం అనేది దేవుని ఉనికిని మనలో అవగాహన చేసుకోవడం.',
    'ఆత్మను జీవితం నుండి తప్పించుకోవడం ద్వారా కాదు, జీవితం లోనే చైతన్యాన్ని మార్పు చేయడం ద్వారా తెలుసుకుంటారు.',
    'ప్రతి నిమిషం ఆధ్యాత్మిక సాధనలో గడిపినప్పుడు, అంతర శాంతి విస్తృతం అవుతుంది.',
    'మనలోని దివ్య జ్వాల అనంత శాంతి యొక్క మూలం.',
    'మనసు అంతర్గతంగా తిరుగుతున్నప్పుడు మానవ అభివృద్ధి వేగంగా జరుగుతుంది.',
    'మనసు యొక్క అశాంతి ఆత్మ యొక్క స్వభావాన్ని కప్పిపుచ్చే ఒక కవచం.',
    'ధ్యానం యొక్క నిశ్శబ్దంలో, ఆత్మ తన శాశ్వత సత్యాన్ని పలుకుతుంది.',
    'నిజమైన శాంతి పరిస్థితుల కంటే మించిపోయింది; ఇది ఒక చైతన్య స్థితి.',
    'ప్రతి ఆధ్యాత్మిక విజయం దివ్యంతో సంబంధాన్ని బలపరుస్తుంది.',
    'దైవం యొక్క ఉనికి సున్నితమైనప్పటికీ నిరంతరంగా ఉంటుంది, భక్తి ద్వారా అందుబాటులో ఉంటుంది.',
    'బ్రహ్మాండం దివ్య చైతన్యానికి వ్యక్తీకరణ.',
    'భయాన్ని అధిగమించడం దైవాత్మలో స్థిరపడటంతో ప్రారంభమవుతుంది.',
    'ధ్యానం ఆత్మ యొక్క అక్షయ స్వభావాన్ని వెల్లడిస్తుంది.',
    'శాశ్వత ఆనందం నిజమైన అన్వేషకుడికి తుది అవగాహన.',
  ],
  [
    Article(
        heading: 'కేవలం దేవుడు',
        body: 'ఎవరూ అన్ని ఆత్మల యొక్క రహస్యాలను తెలుసుకుంటారు, ప్రపంచాన్ని మెరిసేలా చేస్తూ, ఇప్పుడు కోల్పోయి పోయిన వారిని?  \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n\nఅణువులు తమ మెరిసే కళ్ళను మరిచి, సృష్టిలో నాట్యం చేయడానికి ముందు శాశ్వత శూన్యంలో ఒంటరిగా జీవించిన ఎవరు?  \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n\nమనం ఏదో ఒక దానిలో నుంచి వచ్చాము, అది ఏమిటో మాకు తెలియదు. మేము ఇప్పుడు జీవిస్తున్నాము, నవ్వుతున్నాము, మరియు ఆలస్యంగా ఉన్నాము, మరియు మనలో చాలా మంది శాంతియుత మరణం యొక్క కౌగిలిలో పడినప్పుడు, గొప్ప దాటి ఉన్న అడవిలో ఏమి ఉందో తెలియదు. అయినప్పటికీ, ఈ ఉనికికి ముందు మరియు తరువాత జీవితం యొక్క రహస్యం ఎవరు తెలుసుకుంటారు?  \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n\nఅన్ని విషయాలు జీవిస్తున్నాయి; అన్ని విషయాలు శాశ్వత సమ్మేళనంలో నాట్యం చేస్తున్నాయి. సృష్టి యొక్క మహా ప్రదర్శన గురించి ఎవ్వరూ తెలియదు, ఇది అంతరిక్షం యొక్క మాయా గది నుండి ఉద్భవించింది. ఈ అనంత శూన్యంలోని ఈ గది యొక్క ఏ భాగం వస్తువులు మరియు జీవుల ద్వారా ఆక్రమించబడిందో, మరణం యొక్క మాయా కంచు ద్వారా కరిగిపోయినవి, తప్ప – \n\nకేవలం దేవుడు! కేవలం దేవుడు!\n\nమా ప్రియమైన వారు మాకు ప్రేమిస్తారు, మరియు శాశ్వతంగా మాకు ప్రేమించడానికి ప్రమాణం చేస్తారు, కానీ వారు మహాస్వప్నంలో మునిగితే మాకు మర్చిపోతారు. వారి జ్ఞాపకాలు త్వరలో మంచిగా మారిపోతాయి. కానీ, ఎవరు మాకు ఎప్పటికీ ప్రేమిస్తారు, ఎప్పుడూ చెప్పకుండా, మరియు అందరూ మర్చిపోయినప్పుడు ఎవరు మాకు గుర్తు చేస్తారు?\n\nకేవలం దేవుడు! కేవలం దేవుడు!\n\nజీవితం మరియు మరణం, నక్షత్రాలు మరియు గాలి, ప్రేమ మరియు ద్వేషం, దుఃఖం మరియు ఆనందం, మరియు మనిషి మరియు జంతువు కాలం యొక్క స్టిజియన్ మైదానంలో నాట్యం చేస్తారు మరియు నిద్రిస్తారు, మరణంలో దృశ్యాల వెనుక దాచుకొని, మరియు కాలం యొక్క మైదానంలో మాంసపు కొత్త వస్ర్తాలలో మళ్లీ ఆడటానికి బయట వస్తారు. ఎవరూ తనకు ముందుగా ఏమి జరిగిందో, లేదా ఈ ఆసక్తికరమైన కరావన్సరాయిలో ఈ తాత్కాలిక సమావేశం గురించి ఎందుకు ఇంత నిశ్చయంగా ఉన్నాడో గుర్తు చేసుకోరు –  \n  \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n  \nదేవుడు ఈ ఆటను ఎందుకు ఆడుతున్నాడు, మరియు ఆయన ఈ జ్ఞానాన్ని ఎందుకు తనతోనే ఉంచుకుంటున్నాడు, మనతో, ఆయన పిల్లలతో, కేవలం కొంచెం పంచుకుంటున్నాడో –  \n   \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n  \nఅయితే, మీరు ఇకపై తిరుగకుండా, అంతర్యామి తీరానికి దగ్గరగా రాగలిగితే, మరియు మీరు అప్రియమైన పుత్రునిగా ఉన్న స్థితి నుండి నిజమైన ఆకాశీయ సంతానం గా మారితే, అప్పుడు మీరు కూడా తెలుసుకోవాలనుకునే అన్ని విషయాలను –  \n   \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n  \nఅయన అన్ని విషయాలను తెలుసుకుంటున్నందున, మీరు ఒక డిమాండింగ్ సన్ డివైన్ గా మారినప్పుడు, మీరు కూడా అన్ని విషయాలను –  \n   \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n  \nఅన్ని మిత్రులు మీతో విడిచి వెళ్లాల్సినప్పుడు, మీతో ఎవరు ఉంటారు?  \n  \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!  \n  \nఎందుకంటే నిజంగా మీకు ఏది లేదు, ఎవరూ లేదు, ప్రేమించటం నేర్చుకోండి –  \n   \nదేవుడు మాత్రమే! దేవుడు మాత్రమే!'
    ),
    Article(
        heading: 'సంతోషాన్ని పొందడం',
        body: 'పరమహంస యోగానంద, నవంబర్ 1936:\n\nమనం అభివృద్ధి చెందకుండా, దానిలో సంతృప్తి పొందకుండా, మరియు మన ఆనందాన్ని నాశనం చేసే అన్ని ప్రభావాల నుండి రక్షించుకోకుండా ఉండగా, సంతోషంగా ఉండలేము. సంతోషం, నిరీక్షణలో ఉండడం ద్వారా కాదు, కానీ జీవితం యొక్క అన్ని భావాలు మరియు చర్యల్లో దానిని అనుభవించడం ద్వారా వస్తుంది. మీరు ఏం చేస్తున్నా, సంతోషం యొక్క అంతర్గత ప్రవాహాన్ని, ఆనందం యొక్క రహస్య నది, వివిధ ఆలోచనల మట్టిలో మరియు కఠిన పరీక్షల కంకర భూమిలో ప్రవహించనివ్వండి. అన్ని పరిస్థితులలోనూ మీ హృదయంలో రహస్యంగా సంతోషంగా ఉండడం నేర్చుకోండి, మరియు మీకు చెప్పండి, “సంతోషం నా అత్యంత దివ్య జన్మ హక్కు — నా ఆత్మ యొక్క దాచిన ధనం.” నేను చివరకు రాజుల కలల కంటే ఎక్కువగా రహస్యంగా ధనవంతుడిగా మారుతాను అని కనుగొన్నాను. దుఃఖాన్ని ఒక చరిత్రమైన అలవాటుగా మార్చకండి, ఎందుకంటే దుఃఖంగా ఉండటం ఆనందంగా ఉండటం కంటే ఏమీ సంతోషకరం కాదు, మీరు ఆనందంగా ఉన్నప్పుడు మీకు మరియు ఇతరులకు ఇది ఆశీర్వాదం. మీ ముఖంపై వెండి నవ్వు ధరించడం లేదా మీ స్వరంలో మధురమైన ఆనందాన్ని చల్లడం ఎంత సులభమో, ఎందుకు కోపంగా ఉండి మీ చుట్టూ దుఃఖాన్ని చల్లుతారు? నేర్చుకోవడానికి ఎప్పుడూ ఆలస్యమవ్వదు. \n\nఆనందం అది పోషించే దానిపై పెరుగుతుంది. ఎప్పుడూ ఆనందంగా ఉండడం ద్వారా ఆనందంగా ఉండడం నేర్చుకోండి. జాన్ చెప్పాడు, “నాకు డబ్బు వస్తే, నేను ఆనందంగా ఉంటాను.” అతను ధనవంతుడయ్యాడు; తరువాత అతను చెప్పాడు, “నా తీవ్రమైన జీర్ణక్రియను అధిగమిస్తే, నేను ఆనందంగా ఉంటాను.” అతని జీర్ణక్రియ సరి అయినా, అతను ఆలోచించాడు, “నాకు భార్య వస్తే, నేను ఆనందంగా ఉంటాను.” అప్పుడు కలహం మొదలైంది, ఎందుకంటే అతను ఒక కీచకమైన, నోటితో దెబ్బతీసే మహిళను పెళ్లి చేసుకున్నాడు. అతను ఈ భార్యను విడాకులు తీసుకున్నాడు, మరియు చాలా సంవత్సరాల తర్వాత మళ్లీ పెళ్లి చేసుకున్నాడు, కానీ రెండవ భార్య మొదటి భార్య కంటే కూడా చెడు. అప్పుడు అతను రెండవ భార్యను విడాకులు తీసుకుంటే అతనికి ఎక్కువ ఆనందం కలుగుతుందని ఆలోచించాడు, కాబట్టి అతను విడాకులు తీసుకున్నాడు, కానీ ఏడు దశాబ్దాల వయస్సులో అతను ఆలోచించాడు, “లేదు, నేను మళ్లీ యువతను పొందకపోతే నేను ఎప్పుడూ సంతోషంగా ఉండను.” ఈ విధంగా ప్రజలు ప్రయత్నిస్తారు కానీ సంతోషానికి చేరుకోలేరు. వారు తమ స్వంత ముక్కుకు కరివడానికి కోపంతో పరుగెత్తిన మనిషి లాంటివారు, కానీ అది సాధ్యం కాలేదు, ఖచ్చితంగా.\n\nఅజ్ఞానులైన ప్రజలు, జంతువుల్లా, బాధ మరియు ఆనందాన్ని అనుసరించే పాఠాలను పట్టించుకోరు. ఎక్కువ మంది ప్రజలు దు:ఖం మరియు బాధతో నిండిన జీవితాన్ని గడుపుతారు, ఎందుకంటే వారు బాధకు దారితీసే చర్యలను నివారించరు మరియు సంతోషానికి దారితీసే మార్గాలను అనుసరించరు. తరువాత, సంతోషం మరియు దుఖం వచ్చినప్పుడు ఎప్పుడూ అవగాహనతో అధికంగా సున్నితంగా ఉండే వ్యక్తులు ఉంటారు. అలాంటి వ్యక్తులు సాధారణంగా దుఖంతో తీవ్రంగా నాశనం అవుతారు మరియు సంతోషంతో ముంచబడతారు, దీంతో వారి మానసిక సమతుల్యత కోల్పోతారు. అజ్ఞానంలో వేడి వేయించిన తరువాత, దుఖం కలిగించే చర్యలను నివారించడానికి నేర్చుకునే కొద్ది మంది మాత్రమే ఉంటారు.\n\nచాలా మంది సంతోషంగా ఉండాలని కోరుకుంటారు, కానీ వారు సంతోషానికి దారితీసే చర్యలను స్వీకరించడానికి ఎప్పుడూ ప్రయత్నం చేయరు. ఎక్కువ మంది జీవితపు కొండపై కిందకు కూలుతూ, సంతోషపు శిఖరాన్ని ఎక్కాలని మానసికంగా మాత్రమే కోరుకుంటారు. వారు కొన్ని సార్లు, దుఖం యొక్క కిందకు పడిపోవడం నుండి సంతోషానికి ఉన్న ఉత్సాహం నిలబడితే మాత్రమే మేల్కొంటారు. చాలా మంది ఊహాశక్తి లేకుండా ఉంటారు మరియు దుర్ఘటనలు జరగనంత వరకు తమ మూర్ఖత్వం యొక్క భయంకరమైన కలల నుండి మేల్కొనరు. \n\nస్థిరమైన వ్యక్తులు అసంతృప్తిగా ఉంటారు, మరియు అత్యంత అజ్ఞానమైన వ్యక్తులు సంతోషంగా లేదా అసంతృప్తిగా ఉండడం ఎలా అనేది బాగా తెలుసుకోరు. వారు రాళ్లలా భావనలేని వారు. మీ అజ్ఞానంపై అసంతృప్తిగా ఉండటం మంచిది, దానితో సంతోషంగా చనిపోవడం కంటే. మీరు ఎక్కడ ఉన్నా, మీ ఆలోచన, గ్రహణం, మరియు అంతర్దృష్టితో మేల్కొని, జీవించి ఉండండి, మంచి ఫోటోగ్రాఫర్ లాగా, ఆదర్శ ప్రవర్తన యొక్క చిత్రాలను తీసుకోవడానికి ఎల్లప్పుడూ సిద్ధంగా ఉండండి మరియు చెడు ప్రవర్తనను పక్కన పెట్టండి. మీ అత్యున్నత సంతోషం నేర్చుకోవాలని ఎల్లప్పుడూ సిద్ధంగా ఉండటంలో మరియు సరైన ప్రవర్తనలో ఉంది. \n\nసంతోషం కోసం వెతుకుతున్న వ్యక్తులు చెడు అలవాట్ల ప్రభావాన్ని నివారించాలి, అవి దుర్మార్గ చర్యలకు దారితీస్తాయి, ఎందుకంటే దుర్మార్గ చర్యలు ఎప్పుడో ఒకప్పుడు దుఃఖాన్ని ఉత్పత్తి చేస్తాయి. దుఃఖం శరీరం, మనసు, మరియు ఆత్మను మౌనంగా కాల్చే ఆమ్లం లాగా కరిగిస్తుంది, మరియు దీన్ని ఎక్కువ కాలం సహించలేం. అందుకే, దీనిని కఠినంగా నివారించాలి. \n\nచెడు అలవాట్లను మంచి అలవాట్లతో కాటరైజ్ చేసి నయం చేసుకోండి. మీరు అబద్ధాలు చెప్పే చెడు అలవాటులో ఉంటే, మరియు అలా చేసి చాలా స్నేహితులను కోల్పోయి ఉంటే, నిజం చెప్పే మంచి అలవాటును ప్రారంభించండి. మంచి అలవాటు లేదా చెడు అలవాటు ఏర్పడటానికి సమయం పడుతుంది. చెడు వ్యక్తికి మంచి కావడం కష్టమూ, మంచి వ్యక్తికి చెడు కావడం కష్టమూ; అయినప్పటికీ, మీరు మంచి వ్యక్తిగా మారిన తర్వాత, అది మీకు సహజంగా మరియు సులభంగా ఉంటుంది; అలాగే, మీరు చెడు అలవాటును పెంచితే, మీ కోరికల notwithstanding, మీరు చెడు కావడానికి బలవంతులవుతారు, మరియు మీరు ప్రార్థించాలి, “తండ్రా, నా ఆత్మ సిద్ధంగా ఉంది, కానీ నా శరీరం బలహీనంగా ఉంది.” అందువల్ల, సంతోషంగా ఉండే అలవాటును పెంచడం విలువైనది.\n\nచెడు మార్గాల్లో కదులుతున్న వ్యక్తికి ఎటువంటి అడ్డంకి ఉండదు; కానీ అతను ఆధ్యాత్మిక నియమాల ద్వారా తన చెడు అలవాట్లను వ్యతిరేకించడానికి ప్రయత్నించిన వెంటనే, అతని మహత్తర ప్రయత్నాలను అడ్డుకోవడానికి అనేక ప్రలోభాలు ఉత్పత్తి అవుతాయి.\n\nఇతరులను తీర్పు వేయవద్దు\n\nమీ వ్యక్తిగత సంతోషం మీను మరియు మీ కుటుంబాన్ని గాసిప్ చేసే చెడు ఫలితాల నుండి రక్షించడం మీద ఎక్కువగా ఆధారపడి ఉంది. చెడు చూడకు, చెడు మాట్లాడకు, చెడు వినకు, చెడు ఆలోచించకు, చెడు అనుభవించకు. చాలా మంది ఇతరుల గురించి గంటల తరబడి మాట్లాడగలరు మరియు గాసిప్ యొక్క ప్రభావంలో, మద్యం వంటి తాత్కాలిక ప్రభావం క్రింద ఎదుగుతారు. ఇతరుల లోపాల గురించి సంతోషంగా, సులభంగా, మరియు కాటుక విమర్శతో మాట్లాడడం ఎంత విచిత్రం, కానీ తమ స్వంత లోపాల గురించి మాట్లాడటానికి వారు అసహ్యం అనుభవించరు?\n\nమీ స్వంత లోపాల గురించి మాట్లాడటం మీకు ఇష్టమైతే, అది మీకు బాధ కలిగిస్తే, మీరు ఇతరుల గురించి దుర్లక్ష్యంగా, హానికరమైన విషయాలు చెప్పేటప్పుడు మరింత బాధ అనుభవించాలి. మీకు మరియు మీ కుటుంబంలోని ప్రతి సభ్యుడికి ఇతరుల గురించి మాట్లాడకుండా ఉండటానికి శిక్షణ ఇవ్వండి. "మీరు తీర్పు ఇవ్వకండి, మీరు తీర్పు ఇవ్వబడకూడదు." \n\nఒక వ్యక్తి బలహీనతను ప్రజలకు తెలియజేయడం ద్వారా, మీరు అతనికి సహాయం చేయడం లేదు. అదే సమయంలో, మీరు అతన్ని కోపగించడానికి లేదా నిరుత్సాహానికి గురి చేయడానికి కారణమవుతారు, మరియు మీరు అతన్ని అవమానిస్తారు, కాబట్టి అతను మంచి వ్యక్తిగా ఉండాలని ప్రయత్నించడం మానేస్తాడు. ఒక వ్యక్తి యొక్క గౌరవాన్ని బహిరంగంగా దెబ్బతీస్తే, మీరు అతన్ని నిరాశలోకి నెట్టేస్తారు.\n\nఒక వ్యక్తి కష్టాల్లో ఉన్నప్పుడు, అతని స్వంత దుర్మార్గాన్ని బాగా తెలుసుకుంటాడు. విధ్వంసకరమైన విమర్శ ద్వారా, మీరు అతన్ని ఇప్పటికే మునిగిపోయిన నిరాశ యొక్క మట్టిలో మరింతగా నెట్టేస్తారు. అతని గురించి గాసిప్ చేయడం కంటే, మీరు ప్రేమతో, ప్రోత్సాహకమైన మాటలతో అతన్ని బయటకు తీసుకోవాలి. సహాయం కోరినప్పుడు మాత్రమే ఆధ్యాత్మిక మరియు నైతిక సహాయం అందించాలి. మీ స్వంత పిల్లలకు లేదా ప్రియమైన వారికోసం మీరు ఎప్పుడైనా మీ స్నేహపూర్వక, వినమ్రమైన సూచనలను అందించవచ్చు, తద్వారా వారి రహస్యత లేదా సున్నితత్వాన్ని తొలగించవచ్చు.\n\nనవ్వండి మరియు సంతోషంగా ఉండండి\n\nమీ ఇంటిని కన్నీళ్ల లోయగా కాకుండా నవ్వుల లోయగా మార్చండి. ఇప్పుడు నవ్వండి మరియు మీరు అలా చేయడం ఎంత కష్టమయినప్పటికీ పట్టించుకోకండి. ఇప్పుడు నవ్వండి. ఎప్పుడూ నవ్వాలని గుర్తుంచుకోండి, మీరు ఎప్పుడూ నవ్వుతారు.\n\nకొన్ని వ్యక్తులు ఎక్కువ భాగం నవ్వుతారు, కానీ నవ్వుల మాస్క్ క్రింద వారు ఒక దుఃఖం-కోరిన హృదయాన్ని దాచుకుంటారు. అలాంటి వ్యక్తులు అర్థరహిత నవ్వుల నీడల క్రింద నెమ్మదిగా క్షీణిస్తారు. కొన్ని వ్యక్తులు కొన్నిసార్లు నవ్వుతారు, మరియు వారు కొన్ని సమయాల్లో చాలా గంభీరంగా కూడా ఉంటారు; కానీ అందమైన, కఠినమైన బాహ్య రూపం కింద లక్షల నదుల శాంతి నవ్వులు ఉడుకుతున్నాయి.\n\nమీరు ఐదు సంవత్సరాలు మంచి ఆరోగ్యాన్ని అనుభవించి, తరువాత మూడు సంవత్సరాలు ఏ విధమైన చికిత్సతోనూ నయం కాకుండా బాధపడితే, మీరు మంచి ఆరోగ్యాన్ని అనుభవించిన కాలాన్ని మర్చిపోతారు మరియు వ్యాధి గురించి నవ్వుతారు. ఇప్పుడు మీ స్పందన పూర్తిగా వ్యతిరేకంగా ఉండాలి. మీరు మూడు సంవత్సరాలు బాధపడినందున మీరు మళ్లీ ఆరోగ్యంగా ఉండలేరు అని ఆలోచించడం సరైనది కాదు.\n\nఅలాగే, మీరు చాలా కాలం ఆనందంగా ఉంటే, మరియు మీరు తక్కువ కాలం దుఃఖంగా ఉంటే, మీరు మళ్లీ ఆనందంగా ఉండే ఆశను కోల్పోవడానికి సిద్ధంగా ఉంటారు. ఇది ఊహాశక్తి యొక్క లోటు. ఒక దీర్ఘకాలిక ఆనందం యొక్క జ్ఞాపకం మీ అవగాహనను ప్రభావితం చేయడానికి మరియు మీ ప్రస్తుత కష్టాలను దూరం చేయడానికి శక్తివంతమైన అవచేతన అలవాటుగా ఉండాలి. \n\nధనాన్ని మాత్రమే కోల్పోతే, నిజంగా ఏమీ కోల్పోరు, ఎందుకంటే ఆరోగ్యం మరియు నైపుణ్యం ఉంటే, మీరు ఇంకా ఆనందంగా ఉండవచ్చు మరియు మరింత ధనం సంపాదించవచ్చు; కానీ ఆరోగ్యం కోల్పోతే, అప్పుడు ఎక్కువ ఆనందం కూడా కోల్పోతారు, మరియు జీవన సూత్రం కోల్పోతే, అన్ని ఆనందం కోల్పోతుంది. శాంతి సముద్రంలో స్నానం చేసిన తర్వాత, మీరు ఆనందంతో మేల్కొనగానే, “నిద్రలో నేను మానవ కష్టాల నుండి విముక్తి పొందాను. నేను శాంతి రాజు. ఇప్పుడు, నేను రోజు పని చేస్తూ, నా దినచర్య కర్తవ్యం యొక్క యుద్ధాలను కొనసాగిస్తున్నప్పుడు, నిద్రలోని రాజ్యం యొక్క తిరుగుబాటు కష్టాలతో నేను ఇకపై ఓడిపోను” అని చెప్పండి. నేను నిద్రలో శాంతి రాజు, మరియు నేను అవగాహన దేశంలో కూడా అటువంటి రాజుగా కొనసాగిస్తాను. నేను నిద్రలో శాంతి రాజ్యాన్ని వదిలి బయటకు వచ్చినప్పుడు, నా అవగాహన కలల దేశంలో అదే శాంతిని వ్యాపింపజేస్తాను.'
    ),
    Article(
        heading: 'దివ్య ప్రేమ',
        body: 'నీవు హృదయపు గుహల నుండి వచ్చిన మాయాజాల ప్రతిధ్వని, అనుభూతుల వినిపించని స్వరం.\n\nనీవు కనబడని ఆత్మల ఆకర్షణ, నీవు స్నేహం యొక్క గర్భం నుండి ప్రవహించే కుండ.\n\nనీవు ఆత్మల బంధాన్ని కలిగించే కనబడని తార, అనుభూతుల పువ్వులను ప్రేమతో నిండిన, ఆత్మీయమైన కవిత్వం మరియు విశ్వాసపు మాటలుగా మార్చే రహస్య ఉష్ణత యొక్క కిరణాలు.\n\nనీవు దివ్యమైన కామదేవుడు, మాయాజాల ఆత్మలను అన్ని జీవుల హృదయాలను చీల్చడానికి ఆకర్షించే.\n\nనీవు ఆత్మల నిశ్శబ్ద భాష, మరియు ప్రేమికులు తమ హృదయపు పేజీలపై లేఖలు రాయడానికి ఉపయోగించే కనబడని ముద్ర.\n\nనీవు అన్ని ప్రేమల తల్లి, మరియు నీ ప్రేమ గర్భంలో దేవుని హృదయం కొట్టుకుంటోంది.\n\nప్రేమ అనేది అన్ని జీవుల హృదయ స్పందన, మరియు అవతార దూత.\n\nప్రేమ అనేది రెండు హృదయాల మధ్య నిశ్శబ్ద సంభాషణ, మరియు ఇది దేవుని పిలుపు, అన్ని జీవులకి, జీవన మరియు అజీవన, ఆయన ఏకత్వ గృహానికి తిరిగి రాండి.\n\nప్రేమ ఆత్మ పురోగతి తోటలో జన్మిస్తుంది, మరియు ఇది బాహ్య అనుబంధాల చీకటిలో నిద్రిస్తుంది. ఇది హృదయాల బాటల్లో సంరక్షించబడిన ప్రాచీనమైన మరియు మధురమైన అమృతం. \n\nఇది స్వార్థపు చెట్లను కాల్చి, కుటుంబ మరియు దేశభక్తి కుంగు పటాల్ని నాశనం చేసే జ్వాల. \n\nఇది ఆత్మలు, కుటుంబాలు మరియు దేశాల మధ్య ఉన్న అన్ని గోడలను కరిగించే కాంతి. \n\nఇది యువ మరియు ప్రాయపరమైన ఆత్మల తోటలో స్వచ్ఛమైన స్నేహం యొక్క ఎప్పటికీ ముడిపడని పువ్వు. \n\nప్రేమ అనేది స్వర్గానికి దారి, ఆత్మల యొక్క సంపూర్ణ గీతం. \n\nప్రేమ అనేది మౌనమైన రాళ్లలో ప్రతిధ్వనించడానికి ప్రయత్నిస్తున్న దేవుని స్వరం యొక్క ప్రతిధ్వని; ఇది వర్షం, గాలి, సువాసన, జీవన కాంతి మరియు పక్షుల గీతం ద్వారా ప్రతిధ్వనిస్తుంది; ఇది పిల్లల ఏడుపు మరియు నవ్వుల ద్వారా, అచేతన తల్లి ప్రేమ ద్వారా, మరియు మౌన మరియు స్పష్టమైన హృదయాల ద్వారా ప్రతిధ్వనిస్తుంది.'
    ),
    Article(
        heading: 'జీవితంలో ఆనందాన్ని కనుగొనడం',
        body: 'అక్టోబర్ 1936, “జీవితంలో ఆనందాన్ని కనుగొనడం”\n\nమీరు ఒక విషయం పొందలేని వరకు దానిని కోరుకుంటారు; మీరు దానిని పొందిన తర్వాత, త్వరగా లేదా ఆలస్యంగా మీరు దానితో అలసిపోతారు, అప్పుడు మీరు మరొకటి కోరుకుంటారు. మీరు అన్ని సాధించిన కోర్కెల చివరలో మీరు కోరుకునే “మరొకటి” అనే ఆత్మీయమైన విషయాన్ని కనుగొనడానికి ప్రయత్నించారా?\n\nమీరు ఏది కోరుకున్నా, దానిని ఆనందంతో, దానిని పొందడం ద్వారా ఆనందాన్ని పొందే ఆశతో కోరుకోవాలి, మరియు మీరు నిజంగా దానిని పొందినప్పుడు ఆనందంగా అనుభవించాలి. వివిధ విషయాలను నేరుగా లేదా పరోక్షంగా కోరుకుంటున్నప్పుడు, వాస్తవానికి మీరు ఆనందాన్ని కోరుకుంటున్నారు. అన్ని విషయాలను వెతుకుతున్నప్పుడు, మీరు వాస్తవంగా అన్ని ఇష్టాలను నెరవేర్చడం ద్వారా పొందే ఆనందాన్ని వెతుకుతున్నారని అర్థం. \n\nఅప్పుడు, ఆనందాన్ని నేరుగా ఎందుకు వెతకడం లేదు? భౌతిక ఇష్టాలు మరియు భౌతిక విషయాల ద్వారా ఎందుకు దాన్ని వెతుకుతున్నారు? మీరు మీకు దు:ఖాన్ని తెచ్చే వాటిని జీవితం లో కోరడం లేదు. ప్రారంభంలో కొంత ఆనందాన్ని హామీ ఇచ్చే వాటిని కూడా మీరు కోరడం లేదు, కానీ చివరికి మీను లోతైన పశ్చాత్తాపం మరియు బాధలో ముంచేస్తాయి. \n\nచాలా కాలం నిలవని భౌతిక విషయాల అనుగ్రహాన్ని కోరుతూ ఆనందాన్ని ఎందుకు వెతుకుతున్నారు? తాత్కాలిక ఆనందాల కోసం తాత్కాలిక భౌతిక విషయాలపై ఎందుకు ఆధారపడుతున్నారు? భౌతిక విషయాలు మరియు భౌతిక ఇష్టాల నెరవేర్చడం తాత్కాలికమే; అందువల్ల, వాటి నుండి ఉద్భవించే అన్ని ఆనందాలు కూడా తాత్కాలికమే. ఆహారం తినడం, సుగంధాన్ని అనుభవించడం, సంగీతం వినడం, అందమైన వస్తువులను చూడడం, సంతోషకరమైన వస్తువులను స్పర్శించడం వంటి ఆనందాలు తాత్కాలికమైనవి. ఇవి అనుభవాలు ఉత్పత్తి చేసే రుచి, వాసన, శ్రవణ, దృష్టి, మరియు స్పర్శ యొక్క సెన్సేషన్ల కాలం వరకు మాత్రమే ఉంటాయి.\n\nమీరు ఆకర్షణీయమైన ఆనందాన్ని కోరరు; మీరు దుఃఖాన్ని తీసుకొచ్చే తాత్కాలిక ఆనందాన్ని కోరరు; మీరు కాంతి మెరుస్తున్న గోసామర్ రెక్కల కింద క్షణికంగా కన్పించే ఆనందాన్ని కోరరు. మీరు ఎప్పటికీ స్థిరంగా మెరుస్తున్న ఆనందాన్ని కోరాలి, అది ఎప్పటికీ ప్రకాశించే రేడియం లాంటిది.\n\nమీరు చాలా సమానమైన ఆనందాన్ని కూడా కోరరు; మీరు మీ మనసును ఆకట్టించడానికి మరియు మీ దృష్టిని ఎప్పటికీ ఆకర్షించడానికి అనేక మార్గాల్లో మారుతూ, నాట్యం చేసే ఆనందాన్ని కోరుకుంటారు. ఏదైనా ఆనందం క్రమంగా, విరామాలతో వస్తే అది ఆకర్షణీయంగా ఉంటుంది; ఏదైనా monotonous ఆనందం, ఖచ్చితంగా, అలసట కలిగిస్తుంది; కొంతకాలం మాత్రమే వస్తూ, చివరికి దుఃఖాన్ని తెచ్చే ఆనందం అనవసరం. కొంతకాలం వస్తూ, ఆపై క్షీణించి, మీను నిర్లిప్తతలో ముంచేస్తే, మరియు ఈ క్రమంలో ఆ స్థితిని మరింత లోతుగా చేస్తే, అది బాధాకరంగా ఉంటుంది.\n\nనటుడి వివిధ భంగిమల మాదిరిగా ఎప్పుడూ క్రమంగా మారుతున్న ఆనందం, కానీ తనలో మార్పు లేకుండా ఉండే ఆనందమే మనందరికీ కావలసినది. ఇలాంటి ఆనందం కేవలం నియమిత, లోతైన ధ్యానం ద్వారా మాత్రమే పొందవచ్చు. అటువంటి ఎప్పటికీ కొత్త, మార్పు రహిత ఆనందం మాత్రమే మన ఆనందం-తృప్తిని తీర్చగలదు. \n\nప్రకృతి మనకు ఒకేసారి కావలసిన ప్రతిదీ - ధనము, శక్తి, మరియు కోల్పోయిన స్నేహితులు - అందించినట్లయితే, మేము ఈ అన్ని విషయాల నుండి ఎప్పుడో ఒకప్పుడు అలసిపోతాము, కానీ ఒక విషయం మనకు ఎప్పుడూ అలసిపోనిది, అది ఆనందమే. దాని స్వభావం ప్రకారం, ఎప్పటికీ కొత్త ఆనందం మాత్రమే మన మనస్సును అలసిపోనివ్వదు లేదా ఆనందాన్ని మరేదైనా కోసం మార్పిడి చేసుకోవాలని కోరించదు.\n\nచెడు లేదా మంచి అన్వేషణలో, మీరు ఎప్పుడూ ఆనందాన్ని వెతుకుతున్నారని తెలుసుకోండి. మొదటి దాని వాగ్దానం ఆనందం, కానీ దుఃఖాన్ని ఇస్తుంది; రెండవది దుఃఖాన్ని వాగ్దానం చేయవచ్చు కానీ చివరికి నిరంతర ఆనందాన్ని ఖచ్చితంగా ఇస్తుంది. నిరంతర, ఎప్పటికీ కొత్త ఆనందం దేవుడు, మరియు మీరు ఆయనను కనుగొంటే, మీరు ఎప్పుడూ అన్ని నెరవేర్చిన కోరికల చివరలో వెతుకుతున్న శాశ్వతంగా elusive “మరేదైనా” ను పొందుతారు. ఈ "ఇంకా ఏదో"ని కనుగొంటే, మీరు మరింత వెతకరు. ఈ ఎప్పటికీ కొత్త ఆనందాన్ని కనుగొంటే, మీరు ఎప్పుడూ కోరుకున్న ప్రతిదీ అందులోనే కనుగొంటారు.\n\nసంతోషాన్ని ఇచ్చే భౌతిక వస్తువులు మనసుకు బయట ఉంటాయి; అవి కేవలం ఊహ ద్వారా మాత్రమే మనసులోకి ప్రవేశిస్తాయి. ఆనందం, దాని స్వభావం ప్రకారం, మనసులో పుట్టినది మరియు దానికి అత్యంత సమీపంగా ఉంటుంది. బాహ్య, భౌతిక వస్తువులు నాశనం కావచ్చు, కానీ ఈ ఆనందం అంతర్గతంగా నాశనం కావు, అది ఎలా ఉంచాలో తెలిసినప్పుడు మాత్రమే, మరియు ఆనందాన్ని కలిగిన వ్యక్తి తన మనసును మార్చి దుఃఖంగా మారకపోతే. ఈ ఆనందం ఎప్పటికీ కొత్తది మరియు నాశనం కానిది.\n\nభౌతిక మాధ్యమాల ద్వారా లేదా అలాంటి సంబంధాల ద్వారా ఉత్పన్నమైన కోరికల ద్వారా ఆనందాన్ని వెతకవద్దు. మీలోని నిర్దిష్టమైన, నాశనం కాని శుద్ధ ఆనందాన్ని వెతకండి, అప్పుడు మీరు ఎప్పటికీ చైతన్యమయిన, ఎప్పటికీ కొత్త ఆనంద-దేవునిని కనుగొంటారు. ఈ ఆనందం మానసికంగా అభ్యాసించబడిన ఒక అబ్స్ట్రాక్ట్ గుణం కాదు, ఇది చైతన్యమైనది, స్వయంగా ఉత్పన్నమైనది మరియు ఆత్మ యొక్క చైతన్య, స్వయంగా వ్యక్తీకరించే గుణం. దీన్ని అన్వేషించండి మరియు శాశ్వతంగా సంతోషించండి.\n\nమీరు ఈ ఎప్పటికీ కొత్త ఆనందాన్ని పొందినప్పుడు, మీరు అందరినీ ద్వేషించే సైనికుడిగా మారరు. దాని బదులు, మీరు అన్ని విషయాలను సరిగ్గా ఆస్వాదించడానికి అనుకూలమైన స్థితిలో ఉంటారు. దేవుని అమర పిల్లగా, మీరు శాశ్వత ఆనందం యొక్క మీ శాశ్వత స్వభావంతో అన్ని విషయాలను ఆనందించాల్సిన బాధ్యత ఉంది. భౌతిక విషయాలను ఆస్వాదించే వ్యక్తులు భౌతికంగా ఆలోచించే వారిగా మారుతారు. మీరు దేవుని రూపంలో సృష్టించబడినప్పుడు మరియు మీరు అమరుడిగా ఉన్నప్పుడు అసంతృప్తి కలిగిన మానవుడిగా ప్రవర్తించడం అవమానం.\n\nఅమరులు మానవులుగా ప్రవర్తించినప్పుడు, వారు తమ స్వభావంలో ఆనందం, దుఃఖం మరియు నిర్లక్ష్యం యొక్క మార్పులను అనుభవిస్తారు. అది కాబట్టి, మీరు మీ మార్పు చెందని ఆనంద స్వభావంపై ఈ మార్పు చెందగల స్వభావాన్ని నాశనం చేయాలి. మీరు మీ మార్పు చెందని ఆనంద స్వభావాన్ని కనుగొంటే, మీరు మీ మార్పు చెందని, నాశనం కాని ఆనందంతో సుఖమైన లేదా అసుఖమైన ఏదైనా అనుభవించగలుగుతారు. మీ ఆనందం భూమి上的 ఆనందాల పగుల్లల మధ్య అచలంగా నిలబడుతుంది.'
    ),
  ],
);
